          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

